parameters.jsCode:
const formData = $('Code in JavaScript').first().json;
const topic = formData.title || "AI Technology";
let aiContent = items[0].json.choices[0].message.content;

// 1. 清洗内容（只保留正文）
if (aiContent.includes("**")) {
    aiContent = "**" + aiContent.split("**").slice(1).join("**");
}
aiContent = aiContent.split("By creating high-quality")[0].trim();

// 2. 生成【唯一】文件名：日期 + 毫秒级时间戳
const date = new Date().toISOString().split('T')[0];
const timestamp = new Date().getTime(); // 加入毫秒戳防止重复
const safeTopic = topic.toLowerCase().replace(/[^a-z0-9]/g, '-').substring(0, 10);
const fileName = `content-drafts/${date}-${safeTopic}-${timestamp}.md`;

return {
  filename: fileName,
  content: aiContent,
  commit_message: `AI Draft: ${topic}`,
  topic: topic  // ← 加这一行
};

// 1. 直接按节点名称获取数据，不依赖 $input
const contentData = $('Format Generated Content').item.json;
// 2. 逐个字段检查，找到实际有内容的字段
const content = contentData.safeContent 
  || contentData.github_content 
  || contentData.content 
  || 'No Content';
const topic = contentData.topic
  || contentData.safeTopic 
  || contentData.email_subject 
  || 'Untitled Topic';
// 3. 获取图片 URL（兼容 Stable Horde 和 Pollinations）
let imageUrl = '';
try {
  imageUrl = $('Get Image Result').item.json.generations?.[0]?.img || '';
} catch(e) {
  imageUrl = `https://image.pollinations.ai/prompt/${encodeURIComponent(topic + ', professional LinkedIn illustration, business style, no text')}?width=512&height=512&nologo=true`;
}
// 4. 文件路径（加时间戳避免重复）
const rawTopic = contentData.safeTopic || topic;
const timestamp = Date.now();
const fileName = `post_${rawTopic.replace(/[^\w]/g, '_')}_${timestamp}.md`;
// 5. 构造邮件 HTML
const emailHtml = `
  <h2 style="color:#0a66c2;">LinkedIn 内容审批</h2>
  <hr>
  <h3>话题：${topic}</h3>
  <hr>
  <div style="background:#f5f5f5; padding:16px; border-radius:8px;">
    <p style="white-space:pre-wrap;">${content}</p>
  </div>
  <br>
  <p><strong>Generated Image:</strong></p>
  <img src="${imageUrl}" style="max-width:600px; width:100%; border-radius:8px;" />
  <br>
  <p style="font-size:12px; color:#666;">Image URL: <a href="${imageUrl}">${imageUrl}</a></p>
`;
// 6. 返回所有字段
return [{
  json: {
    email_subject: `【项目审批】话题：${topic}`,
    email_html: emailHtml,
    github_file_path: `posts/${fileName}`,
    github_content: `${content}\n\n---\n\n![Generated Image](${imageUrl})\n\nImage URL: ${imageUrl}`,
    safeTopic: topic,
    safeContent: content,
    imageUrl: imageUrl
  }
}];

const xml = $input.first().json.data;

const items = [];
const itemRegex = /<item>([\s\S]*?)<\/item>/g;
let match;

while ((match = itemRegex.exec(xml)) !== null) {
  const itemXml = match[1];

  const title = (itemXml.match(/<title><!\[CDATA\[(.*?)\]\]><\/title>/) || 
                 itemXml.match(/<title>(.*?)<\/title>/) || [])[1] || '';

  const link = (itemXml.match(/<link>(.*?)<\/link>/) || [])[1] || '';

  const snippet = (itemXml.match(/<description><!\[CDATA\[(.*?)\]\]><\/description>/) || 
                   itemXml.match(/<description>(.*?)<\/description>/) || [])[1] || '';

  // 过滤掉太短的文章
  if (title && title.length > 20) {
    items.push({ 
      title: title.replace(/ - .*$/, ''), // 去掉来源名称
      link, 
      contentSnippet: snippet.substring(0, 500) 
    });
  }
}

// 从前20篇里随机选，避免总选同一篇
const pool = items.slice(0, 20);
const randomIndex = Math.floor(Math.random() * pool.length);
const selected = pool[randomIndex] || pool[0];

return [{ json: selected }];

